import { HTMLAttributes } from 'react';
import { cn } from './cn';

type Tone = 'neutral' | 'ia' | 'ok' | 'warn';

export interface TagProps extends HTMLAttributes<HTMLSpanElement> {
  tone?: Tone;
}

/**
 * Tag — rótulo de status curto dentro de listas/cards (ex.: "IA", "Reunião",
 * "Escalado", "Encerrado"). Tons semânticos fixos:
 *   ia    → accent  (ação feita pela IA sozinha)
 *   ok    → ok      (resultado positivo: reunião marcada, pronto)
 *   warn  → warn    (precisa de humano: escalado, pausado)
 *   neutral → cinza (estado final neutro: encerrado, arquivado)
 * Não crie tons novos — mapeie o status para um destes quatro.
 */
export function Tag({ tone = 'neutral', className, ...props }: TagProps) {
  return (
    <span
      className={cn(
        'inline-block rounded-ds border px-1.5 py-0.5 text-xs font-medium',
        tone === 'neutral' && 'border-line bg-surface2 text-tx2',
        tone === 'ia' && 'border-transparent bg-accent-soft text-accent',
        tone === 'ok' && 'border-transparent bg-ok-soft text-ok',
        tone === 'warn' && 'border-transparent bg-warn-soft text-warn',
        className,
      )}
      {...props}
    />
  );
}

/** Chip — pill maior usada em cabeçalhos de página (ex.: "17 ativas · 11 só IA"). */
export function Chip({ className, ...props }: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-2 rounded-ds-full border border-line2 bg-surface px-2.5 py-1 text-sm text-tx2',
        className,
      )}
      {...props}
    />
  );
}

/** Ponto de status "ao vivo" — usar sempre junto de um texto, nunca sozinho. */
export function LiveDot({ className }: { className?: string }) {
  return <span className={cn('inline-block h-1.5 w-1.5 rounded-full bg-ok', className)} />;
}
